<script setup lang="ts">
import { computed, ref } from 'vue'
import { useAppStore } from '@/stores/app-store'
import {
  BACKUP_REMINDER_THRESHOLD_MAX, BACKUP_REMINDER_THRESHOLD_MIN, DEFAULT_BACKUP_REMINDER_THRESHOLD, resolveBackupReminderThreshold,
} from '@/domain/models/settings'

const store = useAppStore()
const reminderEnabled = computed(() => store.settings.backupReminderEnabled !== false)
const thresholdInput = ref<string>(String(resolveBackupReminderThreshold(store.settings.backupReminderThreshold)))
/** 未开启提醒时触发规则不可编辑（readonly 态，点击给吐司引导） */
const editing = computed(() => reminderEnabled.value)

async function toggleReminder(): Promise<void> {
  await store.updateSettings({ backupReminderEnabled: !reminderEnabled.value })
  store.notify(reminderEnabled.value ? '已开启备份提醒' : '已关闭备份提醒', 'success')
}

/** 未开启时点输入框：不进编辑，吐司引导先开启 */
function onThresholdClick(): void {
  if (!editing.value) store.notify('请先开启备份提醒', 'info')
}

async function commitThreshold(): Promise<void> {
  if (!editing.value) return
  const parsed = Number.parseInt(thresholdInput.value, 10)
  if (!Number.isFinite(parsed)) {
    thresholdInput.value = String(DEFAULT_BACKUP_REMINDER_THRESHOLD)
    return
  }
  const resolved = resolveBackupReminderThreshold(parsed)
  thresholdInput.value = String(resolved)
  await store.updateSettings({ backupReminderThreshold: resolved })
  store.notify(`阈值已更新为 ${resolved} 笔`, 'success')
}
</script>

<template>
  <main class="page reminder-page">
    <section class="card form-card">
      <div class="form-row">
        <span class="row-label">备份提醒</span>
        <button
          type="button"
          class="switch"
          role="switch"
          aria-label="备份提醒开关"
          :aria-checked="reminderEnabled"
          :class="{ active: reminderEnabled }"
          @click="toggleReminder"
        ><span /></button>
      </div>
      <div class="form-row column">
        <span class="row-label">触发规则（笔）</span>
        <div class="threshold-input" :class="{ disabled: !editing }">
          <input
            v-model="thresholdInput"
            type="number"
            :min="BACKUP_REMINDER_THRESHOLD_MIN"
            :max="BACKUP_REMINDER_THRESHOLD_MAX"
            inputmode="numeric"
            :readonly="!editing"
            @click="onThresholdClick"
            @change="commitThreshold"
            @blur="commitThreshold"
          />
          <span>笔</span>
        </div>
        <small class="row-hint">开启备份提醒后达到触发规则，将会在首页提醒您备份流水，范围{{ BACKUP_REMINDER_THRESHOLD_MIN }}~{{ BACKUP_REMINDER_THRESHOLD_MAX }}笔</small>
      </div>
    </section>

    <p class="warm-tip">温馨提醒：备份文件请妥善保存（如转发到微信文件传输助手），手机丢失或换机时用它恢复全部账单。</p>
  </main>
</template>

